"""Renumber live Meridian CRM ORD_LINE rows."""

from decimal import Decimal
from typing import Any


def _string_value(value: Any) -> str:
    """Return the legacy string-context representation."""
    return "" if value is None else str(value)


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce LINE_NO for numeric ordering; legacy empty string is zero."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Return copied, live ORD_LINE rows renumbered contiguously per order."""
    ordered: list[tuple[str, Decimal, int, dict]] = []

    for position, source_row in enumerate(lines):
        if _string_value(source_row.get("DEL_FLG", "")) == "Y":
            continue

        row = dict(source_row)
        order_id = _string_value(source_row.get("ORD_ID", ""))
        line_no = _numeric_line_no(source_row.get("LINE_NO", ""))
        ordered.append((order_id, line_no, position, row))

    ordered.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for order_id, _old_line_no, _position, row in ordered:
        if current_order != order_id:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        row["LINE_NO"] = next_line_no
        result.append(row)

    return result
